from collections import Counter


def count_pairs(nums, target):
    seen = Counter()
    count = 0
    for value in nums:
        if seen[target - value] > 0:
            count += 1
        seen[value] += 1
    return count

def count_pairs(nums, target):
    total = 0
    n = len(nums)
    for i in range(n):
        for j in range(i + 1, n):
            if nums[i] + nums[j] == target:
                total += 1
    return total

from collections import Counter


def count_pairs(nums, target):
    freq = Counter(nums)
    total = 0
    for value, times in freq.items():
        other = target - value
        if other == value:
            total += times * (times - 1) // 2
        elif value < other and other in freq:
            total += times * freq[other]
    return total

def count_pairs(nums, target):
    counts = {}
    result = 0
    for x in nums:
        result += counts.get(target - x, 0)
        counts[x] = counts.get(x, 0) + 1
    return result
